          const st = M.SS[k][i], lv = st === 'l', p = M.price[k][i], m = mv(M, k, i), hd = me.hold[i], hv = hd * p, pl = me.cost[i] > 0 ? hv / me.cost[i] - 1 : 0;
          let rc;
